// Drive Verify: the request carries a nonce and nothing else. The folder is a fixed constant.
const FOLDER_ID = 'REPLACE_WITH_DRIVE_FOLDER_ID';
const SCHEMA = 'energygrid.drive_verify.response.v1';

const PROXY_HEADERS = ['cf-ray', 'cf-connecting-ip', 'cf-ipcountry', 'x-forwarded-for', 'x-forwarded-host', 'x-real-ip'];
const item = $input.first().json;
const headers = item && item.headers && typeof item.headers === 'object' ? item.headers : {};
const present = Object.keys(headers).map((key) => key.toLowerCase());
if (PROXY_HEADERS.some((name) => present.includes(name))) {
  // Defence in depth only: a proxy-marked request is answered 404 with no body. It is not the
  // non-public boundary (that is the Cloudflare path exclusion or a private-only listener).
  return [{ json: { route: 'NOT_FOUND' } }];
}
const own = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const body = item ? item.body : undefined;

const keys = own(body) ? Object.keys(body).sort().join('|') : '';
if (keys !== 'nonce|schema' || body.schema !== 'energygrid.drive_verify.request.v1'
    || typeof body.nonce !== 'string' || !/^[0-9a-f]{32}$/.test(body.nonce)) {
  return [{ json: { route: 'REFUSED', response_code: 422,
    response: { schema: SCHEMA, outcome: 'REFUSED', reason: 'EG_VERIFY_REQUEST_INVALID' } } }];
}
return [{ json: { route: 'OK', nonce: body.nonce, folder_id: FOLDER_ID } }];

// Pass Google's own file metadata through unchanged (listed fields only). Complete only when the
// last page has no nextPageToken and no page reported incompleteSearch. The Core decides the rest.
const SCHEMA = 'energygrid.drive_verify.response.v1';
const FIELDS = ['id', 'name', 'mimeType', 'parents', 'size', 'sha256Checksum', 'md5Checksum', 'trashed', 'shortcutDetails'];
const MAX_PAGES = 20;
const request = $('Validate Verify Request').first().json;
const about = $('Get Drive Account').first().json;
const fail = [{ json: { response_code: 502, response: { schema: SCHEMA, nonce: request.nonce, outcome: 'GOOGLE_UNAVAILABLE' } } }];
const user = about && about.statusCode === 200 && about.body && about.body.user ? about.body.user : null;
if (!user || typeof user.emailAddress !== 'string' || !user.emailAddress) return fail;
const pages = $input.all().map((entry) => entry.json);
if (pages.length < 1 || pages.length > MAX_PAGES) return fail;
let incomplete = false;
const files = [];
for (const page of pages) {
  if (!page || page.statusCode !== 200 || !page.body || !Array.isArray(page.body.files)) return fail;
  if (page.body.incompleteSearch === true) incomplete = true;
  for (const file of page.body.files) {
    if (!file || typeof file !== 'object' || Array.isArray(file)) return fail;
    const copy = {};
    for (const key of FIELDS) {
      if (Object.prototype.hasOwnProperty.call(file, key)) copy[key] = file[key];
    }
    files.push(copy);
  }
}
const last = pages[pages.length - 1].body;
const tokenPresent = typeof last.nextPageToken === 'string' && last.nextPageToken.length > 0;
return [{ json: { response_code: 200, response: {
  schema: SCHEMA, nonce: request.nonce, folder_id: request.folder_id, reader_account: user.emailAddress,
  complete: !incomplete && !tokenPresent, pages: pages.length, incomplete_search: incomplete,
  next_page_token_present: tokenPresent, files,
} } }];
